using System.Text.Json;
using AeroScience.Missions;
using AeroScience.Shared;
namespace AeroScience.TestHost;

internal static class LidarProbe
{
    static (string Library,Guid Mission,ScientificSource[] Sources) Existing(string previous)
    {
        using var p=JsonDocument.Parse(File.ReadAllText(Path.Combine(previous,"probe.json")));var j=p.RootElement;if(!j.GetProperty("syntheticFlight").GetBoolean()||!j.GetProperty("genuineHistoricalSources").GetBoolean())throw new IOException("Only an explicitly identified isolated genuine acceptance Library can be reused.");
        var relative=j.GetProperty("sourceLibrary").GetString()!;if(Path.IsPathRooted(relative)||relative.Split(Path.DirectorySeparatorChar).Contains(".."))throw new IOException("Invalid isolated Library reference.");return(Path.GetFullPath(Path.Combine(previous,relative)),j.GetProperty("MissionId").GetGuid(),JsonSerializer.Deserialize<ScientificSource[]>(File.ReadAllText(Path.Combine(previous,"sources.json")),WireJson.Options)!);
    }
    public static async Task Retained(string previous,string destination)
    {
        previous=Path.GetFullPath(previous);destination=Path.GetFullPath(destination);if(Directory.Exists(destination))throw new IOException("Use a new retained-validation directory.");var existing=Existing(previous);var paths=new StorageManager(new PreferenceStore(previous)).Initialize();var missions=new MissionStore(Path.Combine(paths.MissionDirectory,"missions.db"));missions.Initialize();using var science=new ScienceStore(existing.Library);science.Initialize();missions.ScienceLibrary=science;science.RecoverLidarJobs();
        var geometry=science.Artifacts(existing.Mission).Single(a=>a.Kind==ContinuousTerrainSurveys.ArtifactKind);Directory.CreateDirectory(destination);Directory.CreateDirectory(Path.Combine(destination,"tiles"));var results=new List<object>();
        foreach(var group in existing.Sources.Chunk(16)){
            // New partition forces fresh decoding/clipping on the exact tested binary;
            // originals are reused without another network call or numeric copy.
            var review=LidarProcessing.Create(science,missions,existing.Mission,new(geometry.Id,group.Select(s=>new LidarSourceChoice(s.Id,s.ManifestSha256,true)).ToArray(),new(RecordsPerTile:1024,MaximumCandidatePoints:2000000,MaximumScratchBytes:16777216,MaximumOutputBytes:134217728),Guid.NewGuid()));science.ControlLidarJob(review.Id,new(Guid.NewGuid(),review.Revision,"start"));var index=await LidarProcessing.Process(science,missions,review.Id);File.Copy(science.VerifiedArtifactPath(index),Path.Combine(destination,"index-"+review.Id.ToString("N")+".json"));foreach(var c in science.LidarCheckpoints(review.Id))File.Copy(science.VerifiedArtifactPath(science.Artifact(c.ArtifactId)),Path.Combine(destination,"tiles",c.ArtifactId.ToString("N")+".json"));results.Add(new{job=science.LidarJob(review.Id),index.Sha256});
        }
        File.Copy(science.VerifiedArtifactPath(geometry),Path.Combine(destination,"geometry.json"));PreferenceStore.WriteAtomic(Path.Combine(destination,"sources.json"),existing.Sources);PreferenceStore.WriteAtomic(Path.Combine(destination,"probe.json"),new{mode="Offline retained originals after real process restart",syntheticFlight=true,genuineHistoricalSources=true,MissionId=existing.Mission,geometry.Sha256,geometry.InputIdentity,algorithm=LidarProcessing.Algorithm,decoderSource=LidarDecoder.SourceIdentity,sourceLibrary=Path.GetRelativePath(destination,science.DirectoryPath),originalScienceObservations=science.StreamObservations(existing.Mission).Count(),originalScienceProducts=science.Products(existing.Mission).Length,results,networkRequests=0,previousApprovedNetworkReceipt=Path.Combine(previous,"download-receipt.json"),nativeAcceptance="Not Tested"});Console.WriteLine("Restarted retained-source processing completed without network access. Independent comparison still required.");
    }
    public static void DeleteManaged(string previous,string receipt)
    {
        previous=Path.GetFullPath(previous);if(File.Exists(receipt))throw new IOException("Deletion receipt already exists; preserve earlier evidence.");var existing=Existing(previous);var paths=new StorageManager(new PreferenceStore(previous)).Initialize();var missions=new MissionStore(Path.Combine(paths.MissionDirectory,"missions.db"));missions.Initialize();using var science=new ScienceStore(existing.Library);science.Initialize();var coordinator=new MissionCoordinator(missions,1000);
        var sourceIds=existing.Sources.Select(s=>s.Id).ToHashSet();var tiles=science.Artifacts(existing.Mission).Where(a=>a.Kind==LidarProcessing.TileKind).ToArray();var products=tiles.Select(science.VerifiedArtifactPath).ToArray();var recovery=science.CreateRecoveryBackup(Path.Combine(previous,"explicit-owned-recovery"));
        var preview=science.PreviewSourceDeletion(new(sourceIds.ToArray()),missions);if(preview.EligibleSources!=sourceIds.Count)throw new IOException("Genuine source deletion blocked: "+string.Join(';',preview.Sources.SelectMany(s=>s.Blockers)));var result=science.DeleteExternalSources(new(preview.Id,preview.SelectionHash),missions,coordinator.EnterMaintenance);
        var remaining=products.Count(File.Exists)+tiles.Count(t=>File.Exists(Path.Combine(recovery,t.RelativePath)));if(result.State!="Completed"||remaining!=0||science.Sources().Any(s=>sourceIds.Contains(s.Id)))throw new IOException("Managed genuine source values remain pending; deletion is not accepted.");var geometry=science.Artifacts(existing.Mission).Single(a=>a.Kind==ContinuousTerrainSurveys.ArtifactKind);if(ContinuousTerrainSurveys.Status(science,missions,geometry).State!="Current")throw new IOException("Independent modeled geometry changed during source deletion.");PreferenceStore.WriteAtomic(receipt,new{state="Passed",result,selectedSources=sourceIds.Count,managedPointTiles=tiles.Length,remainingManagedNumericTiles=remaining,recoveryCopyVerified=true,geometryPreserved=true,originalFlightSciencePreserved=true,explicitTestExportsPreserved=true,note="This deletes only the marked isolated acceptance Library's managed originals/dependent points; fixture originals and visible evidence exports stay protected."});Console.WriteLine("Genuine managed originals/point tiles purged, including registered recovery copy. Modeled geometry and explicit exports preserved.");
    }
    public static async Task Run(string mode,string original,string destination)
    {
        destination=Path.GetFullPath(destination);original=Path.GetFullPath(original);if(Directory.Exists(destination))throw new IOException("Use a new isolated acceptance directory; no prior results or owner data are overwritten.");
        var paths=new StorageManager(new PreferenceStore(destination)).Initialize();var missions=new MissionStore(Path.Combine(paths.MissionDirectory,"missions.db"));missions.Initialize();
        using var science=new ScienceStore(paths.ScienceLibraryDirectory);science.Initialize();missions.ScienceLibrary=science;var header=LidarLas.Inspect(original);var anchor=(await LidarDecoder.Read(original,header,0,1))[0];var center=LidarCoordinates.Geographic(header.HorizontalCrs!,anchor.X,anchor.Y);ScientificSource[] sources;object? network=null;
        if(mode=="--approve-public-16mib")
        {
            var settings=new ScientificAccessSettings(destination,()=>true);settings.Save(new(true,true,MaximumDownloadBytes:16777216,PreflightTransferBytes:16777216));using var automatic=new AutomaticScientificData(science,settings);var catalog=new LidarCatalog(automatic,science,settings);var area=new GeographicBounds(center.Longitude-.00001,center.Latitude-.00001,center.Longitude+.00001,center.Latitude+.00001);
            var discovery=await catalog.Discover(new(area,Project:"IA_FullState"));PreferenceStore.WriteAtomic(Path.Combine(destination,"discovery.json"),discovery);var selected=discovery.Projects.Single(p=>p.Project=="IA_FullState");
            using var jobs=new ScientificLibraryJobs(science,new(automatic,science,settings),automatic,settings);var preview=await jobs.PreviewLidar(new(selected.Project,selected.MetadataSha256,area,16777216,64,2000000));PreferenceStore.WriteAtomic(Path.Combine(destination,"approved-preview.json"),preview);await jobs.Approve(preview.Id,preview.Preview.SelectionHash);var timer=System.Diagnostics.Stopwatch.StartNew();LibraryDownloadJob current;
            while(true){current=science.LibraryJob(preview.Id);if(current.State is "Completed" or "Failed" or "Interrupted")break;if(timer.Elapsed>TimeSpan.FromMinutes(8))throw new TimeoutException("Bounded genuine EPT acceptance exceeded eight minutes.");await Task.Delay(50);}
            PreferenceStore.WriteAtomic(Path.Combine(destination,"download-receipt.json"),current);if(current.State!="Completed")throw new IOException("Genuine EPT source failed: "+current.Error);sources=current.Items.Select(i=>science.Source(i.SourceId!.Value)!).ToArray();network=new{current.DownloadedBytes,current.CompletedItems,maximumApprovedBytes=16777216,diagnostics=automatic.NetworkDiagnostics()};
        }
        else if(mode=="--offline-local")sources=[await LidarImports.Import(science,original,new("Genuine historical USGS delivered LAZ original","IA_FullState/0-0-0-0","US Government Public Domain","https://registry.opendata.aws/usgs-lidar/ ; root EPT LAZ; source date/datum unknown"))];
        else throw new ArgumentException("Explicit --offline-local or --approve-public-16mib acceptance mode is required.");
        var geometry=LidarWorkflowFixture.Flight(missions,science,center);var products=Path.Combine(destination,"tiles");Directory.CreateDirectory(products);var results=new List<object>();
        foreach(var group in sources.Chunk(16))
        {
            var review=LidarProcessing.Create(science,missions,geometry.MissionId,new(geometry.Id,group.Select(s=>new LidarSourceChoice(s.Id,s.ManifestSha256,true)).ToArray(),new(MaximumCandidatePoints:2000000,MaximumScratchBytes:16777216,MaximumOutputBytes:134217728),Guid.NewGuid()));science.ControlLidarJob(review.Id,new(Guid.NewGuid(),review.Revision,"start"));var index=await LidarProcessing.Process(science,missions,review.Id);
            File.Copy(science.VerifiedArtifactPath(index),Path.Combine(destination,"index-"+review.Id.ToString("N")+".json"));foreach(var tile in science.LidarCheckpoints(review.Id))File.Copy(science.VerifiedArtifactPath(science.Artifact(tile.ArtifactId)),Path.Combine(products,tile.ArtifactId.ToString("N")+".json"));results.Add(new{job=science.LidarJob(review.Id),index.Sha256});
        }
        File.Copy(science.VerifiedArtifactPath(geometry),Path.Combine(destination,"geometry.json"));PreferenceStore.WriteAtomic(Path.Combine(destination,"sources.json"),sources);
        PreferenceStore.WriteAtomic(Path.Combine(destination,"probe.json"),new{mode,syntheticFlight=true,genuineHistoricalSources=true,geometry.MissionId,geometry.Sha256,geometry.InputIdentity,algorithm=LidarProcessing.Algorithm,decoderSource=LidarDecoder.SourceIdentity,results,network,sourceLibrary=Path.GetRelativePath(destination,science.DirectoryPath),originalScienceObservations=science.StreamObservations(geometry.MissionId).Count(),originalScienceProducts=science.Products(geometry.MissionId).Length,nativeAcceptance="Not Tested",independentComparison="Pending laspy/lazrs + PROJ/GEOS comparison",note="Visible exports in this isolated acceptance folder are explicitly retained test evidence, not a hidden application cache."});
        Console.WriteLine(JsonSerializer.Serialize(new{mode,sources=sources.Length,retainedPoints=science.LidarJobs(geometry.MissionId).Sum(j=>j.RetainedPoints),candidatePoints=sources.Sum(s=>s.Manifest.PointCloud!.Originals[0].Header.PointCount),state="Awaiting independent spatial comparison"}));
    }
}
